function s(){const o=document.querySelectorAll(".hero-showcase-tab-btn"),a=document.querySelectorAll(".hero-showcase-panel");o.forEach(t=>{t.addEventListener("click",()=>{const r=t.getAttribute("data-target-idx");r!==null&&(o.forEach(e=>{e.setAttribute("aria-selected","false"),e.className="px-2 py-1 rounded-md text-[11px] font-mono transition-colors border cursor-pointer bg-surface-elevated text-slate-400 hover:text-slate-200 border-hairline hero-showcase-tab-btn"}),t.setAttribute("aria-selected","true"),t.className="px-2 py-1 rounded-md text-[11px] font-mono transition-colors border cursor-pointer bg-blueprint text-white border-blueprint font-semibold hero-showcase-tab-btn",a.forEach((e,n)=>{String(n)===r?(e.classList.remove("hidden"),e.classList.add("block")):(e.classList.add("hidden"),e.classList.remove("block"))}))})})}s();document.addEventListener("astro:page-load",s);
